Class Empleado
  Define nombre As String;

  Method Constructor(n As String)
    This.nombre <- n;
  EndMethod

  Method Presentarse() As String
    Return "Hola, soy " + This.nombre;
  EndMethod
EndClass

Class Cajero Inherits From Empleado
  Method Constructor(n As String)
    Super.constructor(n);
  EndMethod

  Method Presentarse() As String
    Return Super.Presentarse() + " y atiendo la caja";
  EndMethod
EndClass

Algorithm Kiosco
  Define ana As Empleado <- New Empleado("Ana");
  Define beto As Empleado <- New Cajero("Beto");
  Write ana.Presentarse();
  Write beto.Presentarse();
EndAlgorithm

Class Oferta
  Define porcentaje As Integer;
  Method Constructor(p As Integer)
    This.porcentaje <- p;
  EndMethod
  Method Aplicar(precio As Integer) As Integer
    Return precio - precio * This.porcentaje Div 100;
  EndMethod
EndClass

Class Vencimiento
  Define dias As Integer;
  Method Constructor(d As Integer)
    This.dias <- d;
  EndMethod
  Method Aplicar(precio As Integer) As Integer
    If This.dias <= 2 Then
      Return precio Div 2;
    EndIf
    Return precio;
  EndMethod
EndClass

Class Producto
  Define nombre As String;
  Define precio As Integer;
  Define oferta As Oferta;
  Define vencimiento As Vencimiento;
  Method Constructor(n As String, p As Integer)
    This.nombre <- n;
    This.precio <- p;
    This.oferta <- New Oferta(0);
    This.vencimiento <- New Vencimiento(365);
  EndMethod
  Method PonerOferta(nueva As Oferta)
    This.oferta <- nueva;
  EndMethod
  Method PonerVencimiento(fecha As Vencimiento)
    This.vencimiento <- fecha;
  EndMethod
  Method PrecioFinal() As Integer
    Return This.vencimiento.Aplicar(This.oferta.Aplicar(This.precio));
  EndMethod
EndClass

Algorithm Kiosco
  Define jugo As Producto <- New Producto("Jugo", 30);
  Define leche As Producto <- New Producto("Leche", 40);
  leche.PonerVencimiento(New Vencimiento(1));
  Define galletas As Producto <- New Producto("Galletas", 20);
  galletas.PonerOferta(New Oferta(50));
  Define yogur As Producto <- New Producto("Yogur", 40);
  yogur.PonerOferta(New Oferta(25));
  yogur.PonerVencimiento(New Vencimiento(1));
  Write jugo.nombre, " ", jugo.PrecioFinal();
  Write leche.nombre, " ", leche.PrecioFinal();
  Write galletas.nombre, " ", galletas.PrecioFinal();
  Write yogur.nombre, " ", yogur.PrecioFinal();
EndAlgorithm
